<?php
declare(strict_types=1);
ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function discount_json(int $status,array $body):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($body,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())discount_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))discount_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$role=(string)$_SESSION['role'];$allowed=['admin','director','sub_director','headteacher','bursar'];if(!in_array($role,$allowed,true))discount_json(403,['ok'=>false,'message'=>'Your role cannot apply fee discounts.']);if($_SERVER['REQUEST_METHOD']!=='POST')discount_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))discount_json(400,['ok'=>false,'message'=>'Your session expired. Refresh the page and try again.']);
$db=db();$uid=(int)$_SESSION['user_id'];$school=filter_var($_POST['school_id']??null,FILTER_VALIDATE_INT);$pupil=filter_var($_POST['pupil_id']??null,FILTER_VALIDATE_INT);$year=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);$term=trim((string)($_POST['term']??''));$amountRaw=trim((string)($_POST['amount']??''));$amount=filter_var($amountRaw,FILTER_VALIDATE_FLOAT);$reason=trim((string)($_POST['reason']??''));if(!$school||!$pupil||$year===false||$year<2000||$year>2100||$term===''||mb_strlen($term)>40||$amount===false||!preg_match('/^\d+(?:\.\d{1,2})?$/',$amountRaw)||$amount<=0||$amount>100000000||$reason===''||mb_strlen($reason)>255)discount_json(422,['ok'=>false,'message'=>'Enter a valid pupil, academic period, discount amount, and reason.']);$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())discount_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
try{$db->beginTransaction();$q=$db->prepare("SELECT id FROM pupils WHERE id=? AND school_id=? AND status='active' FOR UPDATE");$q->execute([$pupil,$school]);if(!$q->fetchColumn())throw new DomainException('Choose an active pupil in this school.');$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=? AND academic_year=? AND term=?");$q->execute([$school,$pupil,$year,$term]);$balance=(float)$q->fetchColumn();if($amount>$balance)throw new DomainException('Discount cannot exceed the outstanding balance for this pupil and academic period. Current balance: '.number_format($balance,2).'.');$description=mb_substr('Fee discount: '.$reason,0,180);$q=$db->prepare("INSERT INTO school_fee_ledger(school_id,pupil_id,entry_type,academic_year,term,description,amount,recorded_by) VALUES(?,?,'discount',?,?,?,?,?)");$q->execute([$school,$pupil,$year,$term,$description,$amount,$uid]);$entry=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'apply_discount','school_fee_ledger',$entry,json_encode(['school_id'=>$school,'pupil_id'=>$pupil,'academic_year'=>$year,'term'=>$term,'amount'=>$amount,'reason'=>$reason],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)]);$db->commit();$q=$db->prepare('SELECT l.*,u.name recorder,0 is_reversed FROM school_fee_ledger l JOIN users u ON u.id=l.recorded_by WHERE l.id=? AND l.school_id=?');$q->execute([$entry,$school]);$saved=$q->fetch();$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','discount_reversal') THEN amount WHEN entry_type IN ('charge_reversal','discount') THEN -amount ELSE 0 END),0) charges,COALESCE(SUM(CASE WHEN entry_type='payment' THEN amount WHEN entry_type='payment_reversal' THEN -amount ELSE 0 END),0) payments FROM school_fee_ledger WHERE school_id=?");$q->execute([$school]);$totals=$q->fetch();$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=?");$q->execute([$school,$pupil]);$balance=(float)$q->fetchColumn();discount_json(200,['ok'=>true,'message'=>'Fee discount recorded in the pupil ledger.','data'=>['entry'=>$saved,'balance'=>$balance,'charges'=>(float)$totals['charges'],'payments'=>(float)$totals['payments'],'outstanding'=>(float)$totals['charges']-(float)$totals['payments']]]);}catch(DomainException $e){if($db->inTransaction())$db->rollBack();discount_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Fee discount request failed: '.$e->getMessage());discount_json(500,['ok'=>false,'message'=>'The fee discount could not be recorded. Verify the latest fee migration.']);}
